public class ContactTriggerHandler {

    public static void handle(Boolean isBefore, Boolean isInsert, List<Contact> contacts) {
        if (isBefore) {
            handleBefore(isInsert, contacts);
        } else if (isInsert) {
            handleAfterInsert(contacts);
        }
    }

    // ── Before insert / before update ──────────────────────────────────────
    // 1 SOQL: fetch all referenced accounts, copy BillingCountry / AccountSource.
    private static void handleBefore(Boolean isInsert, List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = acctMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    // ── After insert ───────────────────────────────────────────────────────
    // 1 SOQL: fetch accounts that may need phone back-fill.
    // 1 DML:  single update of all affected accounts.
    //
    // Preserves original semantics: contacts are processed in trigger order;
    // the first contact whose phone is non-blank sets the account phone when
    // the account currently has none. Because we mutate the shared Account
    // reference in acctMap, subsequent contacts for the same account see the
    // phone as already populated and skip.
    private static void handleAfterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        // Walk contacts in trigger order; mutate the shared Account in place
        // so that only the first qualifying contact per account wins.
        Map<Id, Account> toUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = acctMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;   // mutates the shared reference
                toUpdate.put(a.Id, a);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate.values();
        }
    }
}
```

