public without sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate and normalise base currency ---
        String base = normalise(baseCurrency);
        if (base == null || !base.matches('^[A-Z]{3}$')) {
            throw new ExchangeRateException('Invalid base currency code: ' + String.valueOf(baseCurrency));
        }

        // --- Validate and normalise quote currencies ---
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String code : quoteCurrencies) {
            String normalised = normalise(code);
            if (normalised == null || !normalised.matches('^[A-Z]{3}$')) {
                throw new ExchangeRateException('Invalid quote currency code: ' + String.valueOf(code));
            }
            normalisedQuotes.add(normalised);
        }

        // --- Build the request ---
        String symbols = String.join(normalisedQuotes, ',');
        String queryString = 'base=' + EncodingUtil.urlEncode(base, 'UTF-8')
                           + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT + '?' + queryString);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        // --- Execute (with single retry on 503) ---
        Http h = new Http();
        HttpResponse res;

        try {
            res = h.send(req);
        } catch (CalloutException e) {
            throw new ExchangeRateException('Callout failed: ' + e.getMessage());
        }

        if (res.getStatusCode() == 503) {
            HttpRequest retryReq = new HttpRequest();
            retryReq.setEndpoint(req.getEndpoint());
            retryReq.setMethod('GET');
            retryReq.setHeader('Accept', 'application/json');

            try {
                res = h.send(retryReq);
            } catch (CalloutException e) {
                throw new ExchangeRateException('Retry callout failed: ' + e.getMessage());
            }
        }

        // --- Check final status ---
        Integer status = res.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Unexpected HTTP status: ' + status);
        }

        // --- Parse and map the response ---
        Map<String, Decimal> result = new Map<String, Decimal>();
        try {
            String body = res.getBody();
            if (body == null || body.trim() == '') {
                throw new ExchangeRateException('Empty response body');
            }

            Map<String, Object> json = (Map<String, Object>) JSON.deserializeUntyped(body);
            if (json == null) {
                throw new ExchangeRateException('Response body is not a valid JSON object');
            }

            Object ratesObj = json.get('rates');
            if (ratesObj == null) {
                throw new ExchangeRateException('Response does not contain a "rates" object');
            }

            Map<String, Object> rates = (Map<String, Object>) ratesObj;

            for (String code : normalisedQuotes) {
                Object rateObj = rates.get(code);
                if (rateObj == null) {
                    throw new ExchangeRateException('No rate returned for currency: ' + code);
                }
                Decimal rate;
                if (rateObj instanceof Decimal) {
                    rate = (Decimal) rateObj;
                } else if (rateObj instanceof Integer) {
                    rate = (Decimal)(Integer) rateObj;
                } else {
                    throw new ExchangeRateException('Unexpected rate type for currency: ' + code);
                }
                result.put(code, rate);
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse response: ' + e.getMessage());
        }

        return result;
    }

    private static String normalise(String code) {
        if (code == null) {
            return null;
        }
        return code.trim().toUpperCase();
    }
}
```

