public class RecordSearchService with sharing {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            // Validate maxRows
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200, got: ' + String.valueOf(maxRows));
            }

            // Validate object name
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required');
            }

            // Look up object (case-insensitive)
            Schema.SObjectType objType = Schema.getGlobalDescribe().get(objectApiName);
            if (objType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }
            Schema.DescribeSObjectResult objDescribe = objType.getDescribe();

            // Check object readability (FLS at object level)
            if (!objDescribe.isAccessible()) {
                throw new SearchException('User does not have read access to object: ' + objDescribe.getName());
            }

            // Validate fields list
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list must not be null or empty');
            }

            // Build case-insensitive field map
            Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();
            for (Map.Entry<String, Schema.SObjectField> entry : objDescribe.fields.getMap().entrySet()) {
                fieldMap.put(entry.getKey().toLowerCase(), entry.getValue());
            }

            // Build SELECT clause
            Set<String> selectFields = new Set<String>();
            selectFields.add('Id');

            for (String field : fields) {
                if (String.isBlank(field)) {
                    throw new SearchException('Field name in fields list cannot be blank');
                }
                Schema.SObjectField sf = fieldMap.get(field.trim().toLowerCase());
                if (sf == null) {
                    throw new SearchException('Field not found on ' + objDescribe.getName() + ': ' + field);
                }
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException('User does not have read access to field: ' + sf.getDescribe().getName());
                }
                selectFields.add(sf.getDescribe().getName());
            }

            // Build WHERE clause
            List<String> whereClauses = new List<String>();
            if (filters != null && !filters.isEmpty()) {
                for (Map.Entry<String, Object> entry : filters.entrySet()) {
                    String filterField = entry.getKey();
                    Object filterValue = entry.getValue();

                    if (String.isBlank(filterField)) {
                        throw new SearchException('Filter field name cannot be blank');
                    }

                    Schema.SObjectField sf = fieldMap.get(filterField.trim().toLowerCase());
                    if (sf == null) {
                        throw new SearchException('Filter field not found on ' + objDescribe.getName() + ': ' + filterField);
                    }
                    if (!sf.getDescribe().isAccessible()) {
                        throw new SearchException('User does not have read access to filter field: ' + sf.getDescribe().getName());
                    }

                    whereClauses.add(sf.getDescribe().getName() + ' = ' + formatSoqlValue(filterValue));
                }
            }

            // Build ORDER BY clause
            String orderByClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.SObjectField sf = fieldMap.get(orderByField.trim().toLowerCase());
                if (sf == null) {
                    throw new SearchException('Order by field not found on ' + objDescribe.getName() + ': ' + orderByField);
                }
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException('User does not have read access to order by field: ' + sf.getDescribe().getName());
                }
                orderByClause = ' ORDER BY ' + sf.getDescribe().getName() + ' ASC';
            }

            // Assemble SOQL
            String soql = 'SELECT ' + String.join(new List<String>(selectFields), ', ') + ' FROM ' + objDescribe.getName();
            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }
            soql += orderByClause;
            soql += ' LIMIT ' + maxRows;

            return Database.query(soql);

        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
