public class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Collect non-blank order numbers from the incoming events
        Set<String> orderNumbers = new Set<String>();
        for (FB_Shipment_Event__e evt : events) {
            if (String.isNotBlank(evt.Order_Number__c)) {
                orderNumbers.add(evt.Order_Number__c);
            }
        }

        if (orderNumbers.isEmpty()) {
            return;
        }

        // One SOQL query: fetch non-cancelled orders matching the event order numbers
        Map<String, FB_Sales_Order__c> orderMap = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c ord : [
            SELECT Id, Order_Number__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNumbers
              AND Status__c != 'Cancelled'
        ]) {
            orderMap.put(ord.Order_Number__c, ord);
        }

        if (orderMap.isEmpty()) {
            return;
        }

        // Build a last-wins map: for each order number, the last event in the list takes precedence
        Map<String, FB_Shipment_Event__e> lastEventMap = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e evt : events) {
            if (String.isNotBlank(evt.Order_Number__c)) {
                lastEventMap.put(evt.Order_Number__c, evt);
            }
        }

        // Apply shipment details from the winning event to each matched order
        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
        for (FB_Sales_Order__c ord : orderMap.values()) {
            FB_Shipment_Event__e evt = lastEventMap.get(ord.Order_Number__c);
            if (evt != null) {
                ord.Status__c = 'Shipped';
                ord.Tracking_Number__c = evt.Tracking_Number__c;
                ord.Carrier__c = evt.Carrier__c;
                ord.Shipped_Date__c = Date.today();
                toUpdate.add(ord);
            }
        }

        // One DML statement
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
